import { Extension } from '@tiptap/core';
import { Plugin } from '@tiptap/pm/state';
import StarterKit from '@tiptap/starter-kit';
import { Markdown } from '@tiptap/markdown';
import { TableKit } from '@tiptap/extension-table';
import TaskList from '@tiptap/extension-task-list';
import TaskItem from '@tiptap/extension-task-item';
import Image from '@tiptap/extension-image';

export const MAX_ANSWER_LENGTH = 200000;

const markdownSyntax = /(^|\n)\s*(?:#{1,6}\s|[-*+]\s|\d+\.\s|>\s|```|\|.+\|)|\*\*[^*\n]+\*\*|__[^_\n]+__|(?:^|\s)(?:\*[^*\n]+\*|_[^_\n]+_|~~[^~\n]+~~|`[^`\n]+`)|\[[^\]]+\]\([^\s)]+\)/;

export function createAnswerExtensions() {
  const AnswerInput = Extension.create({
    name: 'answerInput',
    addProseMirrorPlugins() {
      const editor = this.editor;
      return [new Plugin({
        filterTransaction(transaction) {
          if (!transaction.docChanged) return true;
          return editor.markdown.serialize(transaction.doc.toJSON()).length <= MAX_ANSWER_LENGTH;
        },
        props: {
          handlePaste(view, event) {
            const text = event.clipboardData?.getData('text/plain');
            if (!text || editor.isActive('codeBlock')) return false;
            // Plain-text paste inherits active formatting, including an empty bold toggle.
            if (!markdownSyntax.test(text)) {
              if (event.clipboardData.getData('text/html')) return false;
              const marks = (view.state.storedMarks || view.state.selection.$from.marks()).map(mark => mark.toJSON());
              const paragraphs = text.split(/\r\n?|\n/).map(line => ({ type: 'paragraph',
                content: line ? [{ type: 'text', text: line, marks }] : [] }));
              editor.commands.insertContent(paragraphs);
              return true;
            }
            editor.commands.insertContent(text, { contentType: 'markdown' });
            return true;
          },
        },
      })];
    },
  });
  return [
    StarterKit.configure({ underline: false, link: { openOnClick: false } }),
    TableKit,
    TaskList,
    TaskItem.configure({ nested: true }),
    Image,
    Markdown,
    AnswerInput,
  ];
}
