import React, { useEffect, useMemo, useRef, useState } from 'react';
import { EditorContent, useEditor } from '@tiptap/react';
import { FiList } from 'react-icons/fi';
import { createAnswerExtensions } from './answerEditor.mjs';

export default function AnswerEditor({ value, onChange, number }) {
  const lastValue = useRef(value);
  const [generation, setGeneration] = useState(0);
  useEffect(() => {
    if (value !== lastValue.current) {
      lastValue.current = value;
      // Restored drafts get a new editor, including a fresh undo history.
      setGeneration(previous => previous + 1);
    }
  }, [value]);
  return <EditableAnswer key={generation} initialValue={value} number={number} onChange={text => {
    lastValue.current = text;
    onChange(text);
  }} />;
}

function EditableAnswer({ initialValue, onChange, number }) {
  const change = useRef(onChange);
  change.current = onChange;
  const [formatting, setFormatting] = useState({ bold: false, italic: false, bulletList: false });
  const [empty, setEmpty] = useState(!initialValue);
  const extensions = useMemo(createAnswerExtensions, []);
  const editor = useEditor({
    extensions,
    content: initialValue,
    contentType: 'markdown',
    shouldRerenderOnTransaction: false,
    editorProps: {
      attributes: {
        role: 'textbox',
        'aria-multiline': 'true',
        'aria-label': `Your answer to question ${number}`,
        spellcheck: 'true',
      },
    },
    onUpdate: ({ editor: current }) => change.current(current.getMarkdown()),
    onCreate: ({ editor: current }) => setEmpty(current.isEmpty),
    onTransaction: ({ editor: current }) => {
      setFormatting({ bold: current.isActive('bold'), italic: current.isActive('italic'), bulletList: current.isActive('bulletList') });
      setEmpty(current.isEmpty);
    },
  }, []);
  return <div className="exam-rich-editor" data-empty={empty}>
    <div className="exam-format-toolbar" role="toolbar" aria-label={`Answer formatting for question ${number}`}>
      <button type="button" className="exam-bold-button" disabled={!editor} aria-pressed={formatting.bold}
        onMouseDown={event => event.preventDefault()} onClick={() => editor?.chain().focus().toggleBold().run()}
        aria-label={`Bold text in question ${number}`} title="Bold (⌘/Ctrl+B)"><strong>B</strong></button>
      <button type="button" className="exam-italic-button" disabled={!editor} aria-pressed={formatting.italic}
        onMouseDown={event => event.preventDefault()} onClick={() => editor?.chain().focus().toggleItalic().run()}
        aria-label={`Italic text in question ${number}`} title="Italic (⌘/Ctrl+I)"><em>I</em></button>
      <button type="button" className="exam-list-button" disabled={!editor} aria-pressed={formatting.bulletList}
        onMouseDown={event => event.preventDefault()} onClick={() => editor?.chain().focus().toggleBulletList().run()}
        aria-label={`Bulleted list in question ${number}`} title="Bulleted list"><FiList aria-hidden="true" /></button>
    </div>
    <EditorContent editor={editor} />
  </div>;
}
